# More famous Welsh people, part B: the eighteenth and nineteenth centuries.
# Same format and voice as people2a.py.
from people2a import P

PEOPLE = [
 P("lewis-morris", "tudor", "1701–1765", "Lewis Morris", "Lewis Morris", "Poet and chart maker of Môn", "Bardd a mapiwr o Fôn", "Lewis_Morris", "learning",
   "Anglesey poet, scholar and surveyor who charted the whole coast of Wales and led the Morris brothers’ revival of Welsh learning.",
   "Bardd, ysgolhaig a syrfëwr o Fôn a fapiodd holl arfordir Cymru ac a arweiniodd adfywiad dysg Gymraeg y Morrisiaid.",
   ["Lewis Morris was the eldest of the four Morris brothers of Pentre-eiriannell in Môn, whose letters to each other are one of the treasures of Welsh literature. He was a customs officer, a poet and a tireless collector of old Welsh manuscripts.",
    "In 1737 the Admiralty asked him to survey the coast of Wales, and in 1748 he published Plans of Harbours, Bars, Bays and Roads in St George’s Channel, the first proper charts of the Welsh coast, used by sailors for generations. With his brother Richard he helped found the Honourable Society of Cymmrodorion in London in 1751, and he was mentor to the poet Goronwy Owen."],
   ["Lewis Morris oedd yr hynaf o bedwar Morrisiaid Pentre-eiriannell ym Môn, y mae eu llythyrau at ei gilydd yn un o drysorau llenyddiaeth Gymraeg. Roedd yn swyddog tollau, yn fardd ac yn gasglwr diflino ar hen lawysgrifau Cymraeg.",
    "Yn 1737 gofynnodd y Morlys iddo arolygu arfordir Cymru, ac yn 1748 cyhoeddodd Plans of Harbours, Bars, Bays and Roads in St George’s Channel, y siartiau cywir cyntaf o arfordir Cymru, a ddefnyddiwyd gan forwyr am genedlaethau. Gyda’i frawd Richard helpodd i sefydlu Cymdeithas Anrhydeddus y Cymmrodorion yn Llundain yn 1751, a bu’n fentor i’r bardd Goronwy Owen."]),
 P("richard-wilson", "industrial", "1714–1782", "Richard Wilson", "Richard Wilson", "Father of British landscape painting", "Tad peintio tirluniau Prydain", "Richard_Wilson_(painter)", "art",
   "Painter from Penegoes near Machynlleth, the first great landscape painter of Britain and a founder of the Royal Academy.",
   "Peintiwr o Benegoes ger Machynlleth, peintiwr tirluniau mawr cyntaf Prydain ac un o sylfaenwyr yr Academi Frenhinol.",
   ["Richard Wilson was the son of the rector of Penegoes in Montgomeryshire. He trained as a portrait painter in London and in the 1750s spent seven years in Italy, where he turned to landscape.",
    "Back home he painted the mountains and rivers of Wales and England in a new light: Snowdon from Llyn Nantlle, Cader Idris, Dinas Brân, Caernarfon Castle. He was one of the founding members of the Royal Academy in 1768, and Turner and Constable learned from him. He spent his last years near Mold and is buried at Mold church."],
   ["Mab rheithor Penegoes yn Sir Drefaldwyn oedd Richard Wilson. Hyfforddodd yn beintiwr portreadau yn Llundain ac yn y 1750au treuliodd saith mlynedd yn yr Eidal, lle trodd at dirluniau.",
    "Yn ôl gartref peintiodd fynyddoedd ac afonydd Cymru a Lloegr mewn goleuni newydd: yr Wyddfa o Lyn Nantlle, Cadair Idris, Dinas Brân, Castell Caernarfon. Roedd yn un o aelodau sylfaenol yr Academi Frenhinol yn 1768, a dysgodd Turner a Constable ganddo. Treuliodd ei flynyddoedd olaf ger yr Wyddgrug ac mae wedi’i gladdu yn eglwys yr Wyddgrug."],
   first=("wales", "Called the father of British landscape painting", "Fe’i gelwir yn dad peintio tirluniau Prydain", 1768)),
 P("william-edwards", "industrial", "1719–1789", "William Edwards", "William Edwards", "Builder of the Old Bridge", "Adeiladydd yr Hen Bont", "William_Edwards_(architect)", "enterprise",
   "Self-taught stonemason and minister from Eglwysilan who built the bridge at Pontypridd in 1756, the longest single-span stone arch in the world.",
   "Saer maen a gweinidog hunanddysgedig o Eglwysilan a adeiladodd y bont ym Mhontypridd yn 1756, y bwa carreg unrhychwant hwyaf yn y byd.",
   ["William Edwards was a farmer’s son from Eglwysilan above the Taff who taught himself to build by repairing stone walls. In 1746 he agreed to bridge the River Taff at the place that took its name from his work, Pontypridd.",
    "His first bridge was swept away by a flood, and his second arch fell in. He did not give up. His third, finished in 1756, rose in a single span of 140 feet, with three round holes through each end to lighten the load. It was the longest single-span stone arch bridge in the world, and it still stands. He was also a Nonconformist minister for forty years."],
   ["Mab fferm o Eglwysilan uwchben afon Taf oedd William Edwards, a ddysgodd ei hun i adeiladu drwy drwsio waliau cerrig. Yn 1746 cytunodd i bontio afon Taf yn y man a gymerodd ei enw o’i waith, Pontypridd.",
    "Ysgubwyd ei bont gyntaf ymaith gan lifogydd, a syrthiodd ei ail fwa. Ni roddodd y gorau iddi. Cododd ei drydedd, a orffennwyd yn 1756, mewn un rhychwant o 140 troedfedd, gyda thri thwll crwn drwy bob pen i ysgafnhau’r pwysau. Hon oedd y bont fwa garreg unrhychwant hwyaf yn y byd, ac mae’n sefyll o hyd. Bu hefyd yn weinidog Anghydffurfiol am ddeugain mlynedd."],
   first=("world", "The longest single-span stone arch bridge in the world, Pontypridd 1756", "Y bont fwa garreg unrhychwant hwyaf yn y byd, Pontypridd 1756", 1756)),
 P("richard-price", "industrial", "1723–1791", "Richard Price", "Richard Price", "Friend of liberty", "Cyfaill rhyddid", "Richard_Price", "learning",
   "Philosopher and mathematician from Llangeinor who brought Bayes’ theorem to the world, put life insurance on a sound footing and championed American independence.",
   "Athronydd a mathemategydd o Langeinwyr a ddaeth â theorem Bayes i’r byd, rhoi yswiriant bywyd ar sail gadarn a chefnogi annibyniaeth America.",
   ["Richard Price was born at Tynton, Llangeinor, in Glamorgan and became a minister in London. When his friend Thomas Bayes died, Price found an unfinished essay among his papers, completed it and had it published in 1763. Bayes’ theorem now underpins statistics, medicine and artificial intelligence.",
    "His work on the mathematics of life expectancy helped set the premiums of the Equitable Society, the first modern life insurer. In 1776 his pamphlet on civil liberty, defending the American colonists, sold sixty thousand copies. The American Congress invited him to become a citizen, and in 1781 Yale gave him an honorary doctorate on the same day as George Washington."],
   ["Ganed Richard Price yn Nhynton, Llangeinwyr, ym Morgannwg a daeth yn weinidog yn Llundain. Pan fu farw ei gyfaill Thomas Bayes, cafodd Price draethawd anorffenedig ymhlith ei bapurau, ei gwblhau a’i gyhoeddi yn 1763. Mae theorem Bayes heddiw’n sail i ystadegaeth, meddygaeth a deallusrwydd artiffisial.",
    "Helpodd ei waith ar fathemateg disgwyliad oes i osod premiymau’r Equitable Society, yr yswiriwr bywyd modern cyntaf. Yn 1776 gwerthodd ei bamffled ar ryddid sifil, yn amddiffyn trefedigaethwyr America, drigain mil o gopïau. Gwahoddodd Cyngres America ef i fod yn ddinesydd, ac yn 1781 rhoddodd Iâl ddoethuriaeth er anrhydedd iddo ar yr un diwrnod â George Washington."],
   first=("world", "Brought Bayes’ theorem to the world, 1763", "Daeth â theorem Bayes i’r byd, 1763", 1763)),
 P("goronwy-owen", "industrial", "1723–1769", "Goronwy Owen", "Goronwy Owen", "Poet of exile", "Bardd alltudiaeth", "Goronwy_Owen", "words",
   "Anglesey poet who brought the strict metres back to life and ended his days teaching in Virginia, longing for Môn.",
   "Bardd o Fôn a ddaeth â’r mesurau caeth yn ôl yn fyw ac a ddiweddodd ei ddyddiau’n athro yn Virginia, yn hiraethu am Fôn.",
   ["Goronwy Owen was born at Llanfair Mathafarn Eithaf in Môn. Encouraged by the Morris brothers, he set out to write Welsh poetry in the classical strict metres worthy of Homer and Milton, and his cywyddau inspired the poets of the next century and the revival of the eisteddfod.",
    "Poor and unable to find a parish in Wales, he sailed to Virginia in 1757 to teach at the grammar school of the College of William and Mary, and later became a parson in Brunswick County. His poems of longing for Môn have been loved ever since."],
   ["Ganed Goronwy Owen yn Llanfair Mathafarn Eithaf ym Môn. Wedi’i annog gan y Morrisiaid, aeth ati i ysgrifennu barddoniaeth Gymraeg yn y mesurau caeth clasurol a fyddai’n deilwng o Homer a Milton, ac ysbrydolodd ei gywyddau feirdd y ganrif ddilynol ac adfywiad yr eisteddfod.",
    "Yn dlawd a heb gael plwyf yng Nghymru, hwyliodd i Virginia yn 1757 i ddysgu yn ysgol ramadeg Coleg William a Mary, a daeth wedyn yn berson yn Swydd Brunswick. Mae ei gywydd hiraethus i Fôn wedi’i garu fyth ers hynny."]),
 P("thomas-pennant", "industrial", "1726–1798", "Thomas Pennant", "Thomas Pennant", "Naturalist and traveller", "Naturiaethwr a theithiwr", "Thomas_Pennant", "science",
   "Naturalist of Downing in Flintshire whose Tours in Wales opened the country’s mountains and history to the world.",
   "Naturiaethwr o Downing yn Sir y Fflint yr agorodd ei Deithiau yng Nghymru fynyddoedd a hanes y wlad i’r byd.",
   ["Thomas Pennant of Downing, Whitford, was one of the leading naturalists of Europe. His British Zoology described the animals of the island, and he corresponded with Linnaeus and with Gilbert White, whose Natural History of Selborne began as letters to him.",
    "His Tours in Wales, published from 1778, describe the castles, legends, people and mountains of the country, with a sympathetic account of Owain Glyndŵr. Illustrated by the Welsh artist Moses Griffith, they helped make Wales a place travellers longed to see. Dr Johnson called him the best traveller he had ever read."],
   ["Roedd Thomas Pennant o Downing, Chwitffordd, yn un o naturiaethwyr blaenaf Ewrop. Disgrifiodd ei British Zoology anifeiliaid yr ynys, a bu’n gohebu â Linnaeus ac â Gilbert White, y dechreuodd ei Natural History of Selborne fel llythyrau ato ef.",
    "Mae ei Deithiau yng Nghymru, a gyhoeddwyd o 1778, yn disgrifio cestyll, chwedlau, pobl a mynyddoedd y wlad, gyda hanes cydymdeimladol o Owain Glyndŵr. Wedi’u darlunio gan yr arlunydd o Gymro Moses Griffith, helpasant wneud Cymru’n wlad yr hiraethai teithwyr am ei gweld. Galwodd Dr Johnson ef y teithiwr gorau a ddarllenodd erioed."]),
 P("twm-or-nant", "industrial", "1739–1810", "Twm o’r Nant", "Twm o’r Nant", "The Welsh Shakespeare", "Shakespeare Cymru", "Thomas_Edwards_(Twm_o%27r_Nant)", "words",
   "Thomas Edwards of Llannefydd, carter and playwright, whose comic interludes were acted on wagons in market squares across Wales.",
   "Thomas Edwards o Lannefydd, cariwr a dramodydd, y chwaraewyd ei anterliwtiau doniol ar wagenni mewn sgwariau marchnad ledled Cymru.",
   ["Thomas Edwards was born near Llannefydd in Denbighshire and had almost no schooling. He worked as a carter, a tollgate keeper and a builder, and taught himself to write by copying letters with elderberry juice.",
    "His interludes, verse plays acted on the backs of carts at fairs, mocked greedy landlords, lawyers and tax men to roars of laughter. Plays such as Tri Chryfion Byd, the Three Strong Things of the World, made him the most popular Welsh writer of his day, and he was called the Welsh Shakespeare."],
   ["Ganed Thomas Edwards ger Llannefydd yn Sir Ddinbych a phrin y cafodd ysgol. Gweithiodd yn gariwr, yn geidwad tollborth ac yn adeiladydd, a dysgodd ei hun i ysgrifennu drwy gopïo llythrennau â sudd eirin ysgaw.",
    "Gwnâi ei anterliwtiau, dramâu mydryddol a chwaraeid ar gefn wagenni mewn ffeiriau, hwyl am ben landlordiaid barus, cyfreithwyr a chasglwyr trethi, a’r dorf yn rhuo chwerthin. Gwnaeth dramâu fel Tri Chryfion Byd ef yr awdur Cymraeg mwyaf poblogaidd yn ei ddydd, a’i alw’n Shakespeare Cymru."]),
 P("william-jones-orientalist", "industrial", "1746–1794", "Sir William Jones", "Syr William Jones", "Discoverer of the family of languages", "Darganfyddwr teulu’r ieithoedd", "William_Jones_(philologist)", "learning",
   "Son of the Anglesey mathematician, a genius of languages who first showed that Sanskrit, Greek, Latin and the languages of Europe came from one common source.",
   "Mab y mathemategydd o Fôn, athrylith ieithoedd a ddangosodd gyntaf fod Sansgrit, Groeg, Lladin ac ieithoedd Ewrop yn tarddu o’r un ffynhonnell.",
   ["William Jones was the son of William Jones of Anglesey, who had given the world the symbol π. He mastered more than a dozen languages, became a judge of the Supreme Court in Calcutta, and founded the Asiatic Society of Bengal in 1784.",
    "In a famous address in 1786 he said that Sanskrit, Greek and Latin were so alike that they must have ‘sprung from some common source, which, perhaps, no longer exists’, and that Gothic, Persian and the old British tongue belonged to the same family. It was the beginning of the study of the Indo-European languages, the family to which Welsh belongs."],
   ["Mab William Jones o Fôn, a roddodd y symbol π i’r byd, oedd William Jones. Meistrolodd dros ddwsin o ieithoedd, daeth yn farnwr yn y Goruchaf Lys yn Calcutta, a sefydlodd Gymdeithas Asiatig Bengal yn 1784.",
    "Mewn anerchiad enwog yn 1786 dywedodd fod Sansgrit, Groeg a Lladin mor debyg nes eu bod yn sicr wedi ‘tarddu o ryw ffynhonnell gyffredin, nad yw, efallai, yn bod mwyach’, a bod Gotheg, Perseg a’r hen iaith Frythoneg yn perthyn i’r un teulu. Dyna ddechrau astudio’r ieithoedd Indo-Ewropeaidd, y teulu y perthyn y Gymraeg iddo."],
   first=("world", "First showed that the Indo-European languages are one family, 1786", "Dangosodd gyntaf fod yr ieithoedd Indo-Ewropeaidd yn un teulu, 1786", 1786)),
 P("thomas-charles", "industrial", "1755–1814", "Thomas Charles", "Thomas Charles o’r Bala", "Of Bala", "Y Bala", "Thomas_Charles", "faith",
   "Methodist leader of Bala who built the Sunday schools of Wales and helped found the Bible Society after Mary Jones walked to him for a Bible.",
   "Arweinydd Methodistaidd y Bala a adeiladodd ysgolion Sul Cymru ac a helpodd sefydlu Cymdeithas y Beibl wedi i Mary Jones gerdded ato am Feibl.",
   ["Thomas Charles was born at Llanfihangel Abercywyn in Carmarthenshire and settled at Bala, which he made the centre of Welsh Methodism. He organised circulating schools and then Sunday schools for adults and children alike, so that most of the people of Wales learned to read their Bible in Welsh.",
    "In 1800 a girl called Mary Jones walked twenty-six miles barefoot from Llanfihangel-y-Pennant to buy a Bible from him. Her story, and his appeal for Bibles for Wales, led to the founding of the British and Foreign Bible Society in 1804, which has since given the Scriptures to the world in thousands of languages."],
   ["Ganed Thomas Charles yn Llanfihangel Abercywyn yn Sir Gaerfyrddin ac ymgartrefodd yn y Bala, a wnaeth yn ganolfan Methodistiaeth Cymru. Trefnodd ysgolion cylchynol ac yna ysgolion Sul i oedolion a phlant fel ei gilydd, fel y dysgodd y rhan fwyaf o bobl Cymru ddarllen eu Beibl yn Gymraeg.",
    "Yn 1800 cerddodd merch o’r enw Mary Jones chwe milltir ar hugain yn droednoeth o Lanfihangel-y-Pennant i brynu Beibl ganddo. Arweiniodd ei stori hi, a’i apêl ef am Feiblau i Gymru, at sefydlu’r Feibl Gymdeithas yn 1804, sydd wedi rhoi’r Ysgrythurau i’r byd mewn miloedd o ieithoedd."]),
 P("john-evans-waunfawr", "industrial", "1770–1799", "John Evans", "John Evans o’r Waunfawr", "Explorer of the Missouri", "Fforiwr y Missouri", "John_Evans_(explorer)", "explore",
   "Young man from Waunfawr who went to America to find Madog’s descendants, travelled 1,800 miles up the Missouri and drew the map that guided Lewis and Clark.",
   "Gŵr ifanc o’r Waunfawr a aeth i America i chwilio am ddisgynyddion Madog, teithio 1,800 o filltiroedd i fyny’r Missouri a llunio’r map a dywysodd Lewis a Clark.",
   ["In 1792 John Evans, aged twenty-two, sailed from Wales to find the Welsh-speaking people that travellers said lived on the Missouri, descendants of Madog. He walked west alone, was imprisoned for a time by the Spanish at St Louis, and in 1795 joined a Spanish expedition under James Mackay.",
    "He travelled some 1,800 miles up the Missouri to the villages of the Mandan in what is now North Dakota, raised a flag and spent the winter among them. He found no Welsh speakers, but the map he drew of the river was the best of its day. Thomas Jefferson sent it to Lewis and Clark, and it guided their famous expedition. Evans died in New Orleans in 1799, aged twenty-nine."],
   ["Yn 1792 hwyliodd John Evans, yn ddwy ar hugain oed, o Gymru i chwilio am y bobl Gymraeg y dywedai teithwyr eu bod yn byw ar afon Missouri, disgynyddion Madog. Cerddodd tua’r gorllewin ar ei ben ei hun, bu yng ngharchar y Sbaenwyr yn St Louis am gyfnod, ac yn 1795 ymunodd ag ymgyrch Sbaenaidd dan James Mackay.",
    "Teithiodd tua 1,800 o filltiroedd i fyny’r Missouri i bentrefi’r Mandan yn yr hyn sydd heddiw’n Ogledd Dakota, codi baner a threulio’r gaeaf yn eu plith. Ni chafodd siaradwyr Cymraeg, ond y map a luniodd o’r afon oedd y gorau yn ei ddydd. Anfonodd Thomas Jefferson ef at Lewis a Clark, a thywysodd eu taith enwog. Bu farw Evans yn New Orleans yn 1799, yn naw ar hugain oed."]),
 P("dic-aberdaron", "industrial", "1780–1843", "Dic Aberdaron", "Dic Aberdaron", "The wandering linguist", "Yr ieithydd crwydrol", "Dic_Aberdaron", "learning",
   "Richard Robert Jones of Aberdaron, who taught himself more than a dozen languages and wandered Wales with his books and his cat.",
   "Richard Robert Jones o Aberdaron, a ddysgodd ei hun dros ddwsin o ieithoedd ac a grwydrodd Gymru gyda’i lyfrau a’i gath.",
   ["Richard Robert Jones was the son of a carpenter at the tip of Llŷn. He had little schooling, but from boyhood he taught himself Latin, Greek and Hebrew, and went on to learn French, Italian, Spanish, Arabic, Persian and more.",
    "He spent his life on the roads of Wales and England, his pockets stuffed with books, a cat at his side and a hare-skin cap on his head, working on a great dictionary of Welsh, Greek and Hebrew. He is buried at St Asaph, and Welsh poets have written about him ever since."],
   ["Mab saer coed ym mhen draw Llŷn oedd Richard Robert Jones. Prin y cafodd ysgol, ond o’i blentyndod dysgodd ei hun Ladin, Groeg a Hebraeg, a mynd ymlaen i ddysgu Ffrangeg, Eidaleg, Sbaeneg, Arabeg, Perseg a rhagor.",
    "Treuliodd ei oes ar ffyrdd Cymru a Lloegr, ei bocedi’n llawn llyfrau, cath wrth ei ochr a chap croen ysgyfarnog am ei ben, yn gweithio ar eiriadur mawr Cymraeg, Groeg a Hebraeg. Mae wedi’i gladdu yn Llanelwy, ac mae beirdd Cymru wedi canu amdano fyth ers hynny."]),
 P("john-frost", "industrial", "1784–1877", "John Frost", "John Frost", "Leader of the Newport Rising", "Arweinydd Gwrthryfel Casnewydd", "John_Frost_(Chartist)", "politics",
   "Draper and mayor of Newport who led thousands of Chartists into the town in 1839 to demand the vote for working men.",
   "Dilledydd a maer Casnewydd a arweiniodd filoedd o Siartwyr i’r dref yn 1839 i fynnu’r bleidlais i’r gweithwyr.",
   ["John Frost was a Newport draper who became a magistrate and mayor of the town. He joined the Chartists, who demanded a vote for every man, a secret ballot and pay for MPs so that working people could sit in Parliament.",
    "On 4 November 1839 he led some seven thousand miners and ironworkers down from the valleys into Newport. Soldiers fired on them at the Westgate Hotel and at least twenty-two were killed. Frost was sentenced to death, then transported to Van Diemen’s Land. Pardoned, he came home to a hero’s welcome in 1856 and lived to see working men win the vote. Almost every Chartist demand is now law."],
   ["Dilledydd yng Nghasnewydd oedd John Frost a ddaeth yn ynad ac yn faer y dref. Ymunodd â’r Siartwyr, a fynnai bleidlais i bob dyn, pleidlais gudd a thâl i aelodau seneddol fel y gallai gweithwyr eistedd yn y Senedd.",
    "Ar 4 Tachwedd 1839 arweiniodd tua saith mil o lowyr a gweithwyr haearn i lawr o’r cymoedd i Gasnewydd. Taniodd milwyr arnynt wrth Westy’r Westgate a lladdwyd o leiaf ddau ar hugain. Dedfrydwyd Frost i farwolaeth, yna’i alltudio i Van Diemen’s Land. Wedi’i bardwn daeth adref at groeso arwr yn 1856, a byw i weld gweithwyr yn ennill y bleidlais. Mae bron pob un o ofynion y Siartwyr yn gyfraith heddiw."]),
 P("david-thomas-iron", "industrial", "1794–1882", "David Thomas", "David Thomas", "Father of American anthracite iron", "Tad haearn glo carreg America", "David_Thomas_(industrialist)", "enterprise",
   "Ironmaster from the Neath valley who made iron with anthracite coal at Ynyscedwyn in 1837 and took the method to Pennsylvania.",
   "Meistr haearn o Gwm Nedd a wnaeth haearn â glo carreg yn Ynyscedwyn yn 1837 ac a aeth â’r dull i Bennsylvania.",
   ["David Thomas was born near Neath and became manager at the Ynyscedwyn ironworks in the Swansea valley. The hard anthracite coal of the western coalfield would not burn hot enough to smelt iron, until in 1837, using the new hot blast, Thomas and the owner George Crane made it work.",
    "In 1839 Thomas sailed to Pennsylvania, where there was anthracite in abundance, and in 1840 his furnace at Catasauqua produced iron with it on a large scale. His works grew into one of the biggest in America, and he is honoured there as the father of the American anthracite iron industry."],
   ["Ganed David Thomas ger Castell-nedd a daeth yn rheolwr gwaith haearn Ynyscedwyn yng Nghwm Tawe. Ni losgai glo carreg caled y maes glo gorllewinol yn ddigon poeth i doddi haearn, nes yn 1837, gan ddefnyddio’r chwythiad poeth newydd, i Thomas a’r perchennog George Crane lwyddo.",
    "Yn 1839 hwyliodd Thomas i Bennsylvania, lle roedd digonedd o lo carreg, ac yn 1840 cynhyrchodd ei ffwrnais yn Catasauqua haearn ag ef ar raddfa fawr. Tyfodd ei waith yn un o’r mwyaf yn America, ac fe’i hanrhydeddir yno fel tad diwydiant haearn glo carreg America."],
   first=("world", "First to smelt iron successfully with anthracite coal, Ynyscedwyn 1837", "Y cyntaf i doddi haearn yn llwyddiannus â glo carreg, Ynyscedwyn 1837", 1837)),
 P("hugh-owen", "industrial", "1808–1881", "Sir Hugh Owen", "Syr Hugh Owen", "Builder of Welsh education", "Adeiladydd addysg Cymru", "Hugh_Owen_(educationist)", "learning",
   "Anglesey-born campaigner who did more than anyone to give Wales its schools, its first university college and the modern National Eisteddfod.",
   "Ymgyrchydd o Fôn a wnaeth fwy na neb i roi i Gymru ei hysgolion, ei choleg prifysgol cyntaf a’r Eisteddfod Genedlaethol fodern.",
   ["Hugh Owen was born at Y Foel, Llangeinwen, in Môn and spent his working life as a civil servant in London. In his spare hours he gave himself to the education of Wales. In 1843 he called on the people to found British Schools, and hundreds were opened across the country.",
    "He led the campaign for a university for Wales, and in 1872 the University College of Wales opened in an unfinished hotel on the seafront at Aberystwyth, paid for by the pennies of chapel collections. He also helped found the National Eisteddfod Association and colleges for training teachers. His statue stands in Caernarfon."],
   ["Ganed Hugh Owen yn y Foel, Llangeinwen, ym Môn a threuliodd ei oes waith yn was sifil yn Llundain. Yn ei oriau hamdden rhoddodd ei hun i addysg Cymru. Yn 1843 galwodd ar y bobl i sefydlu Ysgolion Brutanaidd, ac agorwyd cannoedd ledled y wlad.",
    "Arweiniodd yr ymgyrch am brifysgol i Gymru, ac yn 1872 agorodd Coleg Prifysgol Cymru mewn gwesty anorffenedig ar lan y môr yn Aberystwyth, wedi’i dalu gan geiniogau casgliadau’r capeli. Helpodd hefyd sefydlu Cymdeithas yr Eisteddfod Genedlaethol a cholegau hyfforddi athrawon. Saif ei gerflun yng Nghaernarfon."]),
 P("evan-james", "industrial", "1809–1878", "Evan James and James James", "Evan James a James James", "Father and son of the anthem", "Tad a mab yr anthem", "Evan_James", "music",
   "The weaver of Pontypridd and his harpist son who wrote Hen Wlad Fy Nhadau in January 1856, the national anthem of Wales.",
   "Gwehydd Pontypridd a’i fab y telynor a gyfansoddodd Hen Wlad Fy Nhadau yn Ionawr 1856, anthem genedlaethol Cymru.",
   ["Evan James, Ieuan ab Iago, was a weaver and woollen manufacturer in Pontypridd, and a poet. His son James James, Iago ap Ieuan, played the harp in the town’s inns. Family tradition says that in January 1856 James composed a tune while walking by the River Rhondda, and his father wrote words to it that same evening.",
    "They called it Glan Rhondda. It was first sung in the vestry of Capel Tabor in Maesteg, spread through the eisteddfodau, and became Hen Wlad Fy Nhadau, the anthem of Wales. In 1905 it became the first national anthem sung before a sporting match. A memorial to father and son stands in Ynysangharad Park in Pontypridd."],
   ["Gwehydd a gwneuthurwr gwlân ym Mhontypridd, a bardd, oedd Evan James, Ieuan ab Iago. Canai ei fab James James, Iago ap Ieuan, y delyn yn nhafarnau’r dref. Yn ôl traddodiad y teulu, yn Ionawr 1856 cyfansoddodd James dôn wrth gerdded ar lan afon Rhondda, ac ysgrifennodd ei dad eiriau iddi’r un noson.",
    "Glan Rhondda oedd eu henw arni. Fe’i canwyd gyntaf yn festri Capel Tabor ym Maesteg, ymledodd drwy’r eisteddfodau, a daeth yn Hen Wlad Fy Nhadau, anthem Cymru. Yn 1905 hi oedd yr anthem genedlaethol gyntaf i’w chanu cyn gêm chwaraeon. Saif cofeb i’r tad a’r mab ym Mharc Ynysangharad ym Mhontypridd."],
   first=("world", "Hen Wlad Fy Nhadau: the first national anthem sung before a sporting match, 1905", "Hen Wlad Fy Nhadau: yr anthem genedlaethol gyntaf i’w chanu cyn gêm chwaraeon, 1905", 1905)),
 P("twm-carnabwth", "industrial", "c. 1806–1876", "Twm Carnabwth", "Twm Carnabwth", "The first Rebecca", "Y Becca gyntaf", "Twm_Carnabwth", "politics",
   "Thomas Rees of Mynachlog-ddu, who led the first Rebecca attack on a tollgate, at Efail-wen in 1839.",
   "Thomas Rees o Fynachlog-ddu, a arweiniodd ymosodiad cyntaf Merched Beca ar dollborth, yn Efail-wen yn 1839.",
   ["The farmers of west Wales were crushed by rents, tithes and the tolls charged at gates on every road. On the night of 13 May 1839 a crowd with blackened faces, led by a tall man in a woman’s dress, smashed the new tollgate at Efail-wen on the Carmarthenshire border. Their leader was Thomas Rees of Carnabwth, a prize-fighter and farmer of Mynachlog-ddu.",
    "The rioters called their leader Rebecca, after the blessing in Genesis that Rebekah’s seed would ‘possess the gate of those which hate them’. Over the next four years Merched Beca destroyed tollgates across south-west Wales, and in 1844 the government gave way and reformed the tolls. Twm is buried at Bethel chapel, Mynachlog-ddu."],
   ["Roedd ffermwyr gorllewin Cymru wedi’u llethu gan renti, degymau a’r tollau a godid wrth gatiau ar bob ffordd. Ar noson 13 Mai 1839 drylliodd tyrfa wedi duo’u hwynebau, dan arweiniad gŵr tal mewn gwisg menyw, y tollborth newydd yn Efail-wen ar ffin Sir Gaerfyrddin. Eu harweinydd oedd Thomas Rees o Garnabwth, paffiwr a ffermwr o Fynachlog-ddu.",
    "Galwai’r terfysgwyr eu harweinydd yn Rebecca, ar ôl y fendith yn Genesis yr etifeddai had Rebeca ‘borth ei gaseion’. Dros y pedair blynedd nesaf dinistriodd Merched Beca dollbyrth ar draws y de-orllewin, ac yn 1844 ildiodd y llywodraeth a diwygio’r tollau. Mae Twm wedi’i gladdu yng nghapel Bethel, Mynachlog-ddu."]),
 P("lady-charlotte-guest", "industrial", "1812–1895", "Lady Charlotte Guest", "Arglwyddes Charlotte Guest", "Translator of the Mabinogion", "Cyfieithydd y Mabinogion", "Lady_Charlotte_Guest", "words",
   "Learned Welsh at Dowlais, translated the Mabinogion into English and ran the largest ironworks in the world.",
   "Dysgodd Gymraeg yn Nowlais, cyfieithodd y Mabinogion i’r Saesneg a rheolodd waith haearn mwyaf y byd.",
   ["Charlotte Bertie married John Guest, master of the Dowlais ironworks at Merthyr, in 1833 and made Wales her home. She learned Welsh, and with the help of the scholars Thomas Price, Carnhuanawc, and John Jones, Tegid, she translated the tales of the Red Book of Hergest.",
    "Her Mabinogion, published between 1838 and 1849, brought Pwyll, Branwen, Culhwch and Olwen, and the Dream of Macsen to readers all over the world, and gave the collection the name it is known by. After her husband died in 1852 she ran Dowlais herself, then the largest ironworks on earth."],
   ["Priododd Charlotte Bertie â John Guest, meistr gwaith haearn Dowlais ym Merthyr, yn 1833 a gwneud Cymru’n gartref. Dysgodd Gymraeg, a chyda chymorth yr ysgolheigion Thomas Price, Carnhuanawc, a John Jones, Tegid, cyfieithodd chwedlau Llyfr Coch Hergest.",
    "Daeth ei Mabinogion, a gyhoeddwyd rhwng 1838 a 1849, â Phwyll, Branwen, Culhwch ac Olwen a Breuddwyd Macsen i ddarllenwyr ledled y byd, a rhoi i’r casgliad yr enw yr adwaenir ef wrtho. Wedi i’w gŵr farw yn 1852 rheolodd Ddowlais ei hun, gwaith haearn mwyaf y byd ar y pryd."],
   first=("world", "The first full translation of the Mabinogion into English, 1838–49", "Y cyfieithiad Saesneg llawn cyntaf o’r Mabinogion, 1838–49", 1838)),
 P("mary-dillwyn", "industrial", "1816–1906", "Mary Dillwyn", "Mary Dillwyn", "The first woman photographer in Wales", "Y ffotograffydd benywaidd cyntaf yng Nghymru", "Mary_Dillwyn", "art",
   "Swansea pioneer of photography whose relaxed pictures of family, children and pets from the 1850s include the oldest known photograph of a snowman.",
   "Arloeswr ffotograffiaeth o Abertawe y mae ei lluniau hamddenol o deulu, plant ac anifeiliaid o’r 1850au yn cynnwys y llun hynaf y gwyddys amdano o ddyn eira.",
   ["Mary Dillwyn belonged to a Swansea family of scientists. Her brother John Dillwyn Llewelyn, whose wife was a cousin of Fox Talbot, the inventor of photography, was a pioneer of the camera, and in the early 1850s she took it up herself at Penllergaer.",
    "She is the first known woman photographer in Wales. While others posed their sitters stiffly, she caught children laughing, dogs and cats, flowers and family life. Her picture of a snowman, taken around 1853, is the earliest known photograph of one anywhere in the world."],
   ["Perthynai Mary Dillwyn i deulu o wyddonwyr yn Abertawe. Roedd ei brawd John Dillwyn Llewelyn, yr oedd ei wraig yn gyfnither i Fox Talbot, dyfeisiwr ffotograffiaeth, yn arloeswr y camera, ac yn gynnar yn y 1850au cymerodd hithau’r camera ym Mhenlle’r-gaer.",
    "Hi yw’r ffotograffydd benywaidd cyntaf y gwyddys amdani yng Nghymru. Tra gosodai eraill eu gwrthrychau’n stiff, daliai hi blant yn chwerthin, cŵn a chathod, blodau a bywyd teulu. Ei llun o ddyn eira, a dynnwyd tua 1853, yw’r ffotograff cynharaf y gwyddys amdano o un yn unman yn y byd."],
   first=("world", "The oldest known photograph of a snowman, c. 1853", "Y ffotograff hynaf y gwyddys amdano o ddyn eira, tua 1853", 1853)),
 P("david-davies-llandinam", "industrial", "1818–1890", "David Davies", "David Davies, Llandinam", "Top Sawyer", "Top Sawyer", "David_Davies_(industrialist)", "enterprise",
   "Sawyer’s son from Llandinam who built railways across mid Wales, sank the Rhondda’s richest pits and built Barry Docks.",
   "Mab llifiwr o Landinam a adeiladodd reilffyrdd ar draws canolbarth Cymru, suddo pyllau cyfoethocaf y Rhondda ac adeiladu Dociau’r Barri.",
   ["David Davies left school at eleven to work as a sawyer, and was nicknamed Top Sawyer because he always took the top end of the saw pit. He built bridges and then railways through mid Wales, among them the line through the great cutting at Talerddig, the deepest in the world when it was dug.",
    "In 1864 he struck the rich steam coal of the upper Rhondda, and his Ocean Coal Company became one of the biggest in Wales. When the Cardiff docks could not cope, he built his own at Barry, opened in 1889. A generous chapel man, he gave money to the university college at Aberystwyth. His grandchildren gave Gregynog and great art collections to Wales."],
   ["Gadawodd David Davies yr ysgol yn un ar ddeg i weithio’n llifiwr, a’i alw’n Top Sawyer am mai ef a gymerai ben uchaf y pwll llifio bob amser. Adeiladodd bontydd ac yna reilffyrdd drwy’r canolbarth, yn eu plith y lein drwy’r toriad mawr yn Nhalerddig, y dyfnaf yn y byd pan gafodd ei gloddio.",
    "Yn 1864 trawodd ar lo stêm cyfoethog y Rhondda uchaf, a daeth ei Gwmni Glo Ocean yn un o’r mwyaf yng Nghymru. Pan na allai dociau Caerdydd ymdopi, adeiladodd ei rai ei hun yn y Barri, a agorwyd yn 1889. Dyn capel hael ydoedd, a rhoddodd arian i’r coleg prifysgol yn Aberystwyth. Rhoddodd ei wyrion Gregynog a chasgliadau celf mawr i Gymru."]),
 P("john-hughes-yuzovka", "industrial", "1814–1889", "John Hughes", "John Hughes", "Founder of a city in Ukraine", "Sylfaenydd dinas yn Wcráin", "John_Hughes_(businessman)", "enterprise",
   "Merthyr engineer who founded the ironworks and the town of Hughesovka in Ukraine in 1869, the city now called Donetsk.",
   "Peiriannydd o Ferthyr a sefydlodd y gwaith haearn a thref Hughesovka yn Wcráin yn 1869, y ddinas a elwir heddiw’n Donetsk.",
   ["John Hughes was the son of an engineer at the Cyfarthfa ironworks in Merthyr. He became a famous engineer and manager in London, designing armour plate and gun mountings for warships.",
    "In 1869 the Russian government invited him to build an ironworks on the steppe of the Donbas. He sailed with eight ships of equipment and a hundred skilled workers from south Wales, and the settlement that grew around his works was named Hughesovka, Yuzovka in Russian. It grew into the great city of Donetsk. Hughes is buried in West Norwood, London."],
   ["Mab peiriannydd yng ngwaith haearn Cyfarthfa ym Merthyr oedd John Hughes. Daeth yn beiriannydd a rheolwr enwog yn Llundain, yn cynllunio platiau arfwisg a gosodiadau gynnau i longau rhyfel.",
    "Yn 1869 gwahoddodd llywodraeth Rwsia ef i adeiladu gwaith haearn ar baith y Donbas. Hwyliodd gydag wyth llong o offer a chant o weithwyr medrus o dde Cymru, ac enwyd y gymuned a dyfodd o gwmpas ei waith yn Hughesovka, Yuzovka yn Rwsieg. Tyfodd yn ddinas fawr Donetsk. Mae Hughes wedi’i gladdu yn West Norwood, Llundain."]),
 P("isaac-roberts", "industrial", "1829–1904", "Isaac Roberts", "Isaac Roberts", "Photographer of the galaxies", "Ffotograffydd y galaethau", "Isaac_Roberts", "science",
   "Farmer’s son from near Denbigh who took the first photograph to show that the Andromeda nebula is a spiral, in 1888.",
   "Mab fferm o gyffiniau Dinbych a dynnodd y ffotograff cyntaf i ddangos mai troell yw nifwl Andromeda, yn 1888.",
   ["Isaac Roberts was born at Groes near Denbigh and moved to Liverpool, where he made his fortune as a builder. He spent it on astronomy, building telescopes and pioneering the long-exposure photography of the night sky.",
    "On 29 December 1888 he exposed a plate on the Andromeda nebula for four hours and revealed, for the first time, its spiral arms. We now know it as a whole galaxy, two and a half million light years away. His Photographs of Stars, Star-clusters and Nebulae won him the gold medal of the Royal Astronomical Society."],
   ["Ganed Isaac Roberts yn y Groes ger Dinbych a symudodd i Lerpwl, lle gwnaeth ei ffortiwn yn adeiladydd. Gwariodd hi ar seryddiaeth, yn adeiladu telesgopau ac yn arloesi â ffotograffiaeth amlygiad hir o awyr y nos.",
    "Ar 29 Rhagfyr 1888 amlygodd blât ar nifwl Andromeda am bedair awr a datgelu, am y tro cyntaf, ei breichiau troellog. Gwyddom heddiw mai galaeth gyfan yw hi, ddwy filiwn a hanner o flynyddoedd goleuni i ffwrdd. Enillodd ei Photographs of Stars, Star-clusters and Nebulae fedal aur y Gymdeithas Seryddol Frenhinol iddo."],
   first=("world", "The first photograph to show the spiral shape of the Andromeda galaxy, 1888", "Y ffotograff cyntaf i ddangos siâp troellog galaeth Andromeda, 1888", 1888)),
 P("david-edward-hughes", "industrial", "1831–1900", "David Edward Hughes", "David Edward Hughes", "Inventor of the microphone", "Dyfeisiwr y meicroffon", "David_E._Hughes", "science",
   "Inventor from a Corwen family who built the carbon microphone in 1878 and was the first to send and receive radio waves, in 1879.",
   "Dyfeisiwr o deulu o Gorwen a adeiladodd y meicroffon carbon yn 1878 ac a oedd y cyntaf i anfon a derbyn tonnau radio, yn 1879.",
   ["David Edward Hughes was born in 1831 to a Welsh-speaking family of musicians from the Corwen and Bala country; Corwen claims him as its own. The family emigrated to America, where he became a music teacher, and in 1855 he invented a printing telegraph that was used across Europe.",
    "In 1878 in London he built the carbon microphone, the ancestor of every telephone mouthpiece for a hundred years, and gave the word microphone its modern meaning. He refused to patent it, so that everyone could use it. In 1879 he sent and received radio signals along Great Portland Street, years before Hertz proved that radio waves exist. He left his fortune to London hospitals."],
   ["Ganed David Edward Hughes yn 1831 i deulu Cymraeg o gerddorion o ardal Corwen a’r Bala; mae Corwen yn ei hawlio’n fab iddi. Ymfudodd y teulu i America, lle daeth yn athro cerdd, ac yn 1855 dyfeisiodd delegraff argraffu a ddefnyddid ledled Ewrop.",
    "Yn 1878 yn Llundain adeiladodd y meicroffon carbon, hynafiad pob ffôn am ganrif, a rhoi i’r gair microffon ei ystyr fodern. Gwrthododd ei batentu, er mwyn i bawb gael ei ddefnyddio. Yn 1879 anfonodd a derbyniodd signalau radio ar hyd Great Portland Street, flynyddoedd cyn i Hertz brofi fod tonnau radio’n bod. Gadawodd ei ffortiwn i ysbytai Llundain."],
   first=("world", "The carbon microphone, 1878, and the first radio signals sent and received, 1879", "Y meicroffon carbon, 1878, a’r signalau radio cyntaf i’w hanfon a’u derbyn, 1879", 1878)),
 P("hugh-owen-thomas", "industrial", "1834–1891", "Hugh Owen Thomas", "Hugh Owen Thomas", "Father of orthopaedic surgery", "Tad llawfeddygaeth orthopedig", "Hugh_Owen_Thomas", "science",
   "Son of an Anglesey bone-setting family whose Thomas splint saved tens of thousands of lives in the First World War.",
   "Mab i deulu o feddygon esgyrn o Fôn y bu sblint Thomas yn achub degau o filoedd o fywydau yn y Rhyfel Byd Cyntaf.",
   ["Hugh Owen Thomas was born at Bodedern in Môn, into a family famous for generations as bone-setters. He trained as a doctor and set up practice in Liverpool, where he treated the dockers and the poor, often without charge.",
    "He invented the Thomas splint for broken thigh bones. When his nephew Robert Jones brought it into use on the Western Front in 1916, deaths from such wounds fell from about four in five to fewer than one in five. He is honoured as the father of orthopaedic surgery in Britain."],
   ["Ganed Hugh Owen Thomas ym Modedern ym Môn, i deulu a fu’n enwog am genedlaethau fel meddygon esgyrn. Hyfforddodd yn feddyg a sefydlu practis yn Lerpwl, lle bu’n trin gweithwyr y dociau a’r tlodion, yn aml heb dâl.",
    "Dyfeisiodd sblint Thomas ar gyfer esgyrn clun wedi’u torri. Pan ddaeth ei nai Robert Jones ag ef i ddefnydd ar Ffrynt y Gorllewin yn 1916, syrthiodd marwolaethau o glwyfau o’r fath o tua phedwar o bob pump i lai nag un o bob pump. Fe’i hanrhydeddir fel tad llawfeddygaeth orthopedig ym Mhrydain."],
   first=("world", "Invented the Thomas splint, which cut deaths from broken thigh bones from 80% to under 20%", "Dyfeisiodd sblint Thomas, a dorrodd farwolaethau o glun wedi’i thorri o 80% i lai na 20%", 1875)),
 P("pryce-pryce-jones", "industrial", "1834–1920", "Sir Pryce Pryce-Jones", "Syr Pryce Pryce-Jones", "Inventor of mail order", "Dyfeisiwr archebu drwy’r post", "Pryce_Pryce-Jones", "enterprise",
   "Draper of Newtown who started the world’s first mail-order business in 1861, selling Welsh flannel to Queen Victoria and Florence Nightingale.",
   "Dilledydd o’r Drenewydd a ddechreuodd fusnes archebu drwy’r post cyntaf y byd yn 1861, gan werthu gwlanen Gymreig i’r Frenhines Fictoria a Florence Nightingale.",
   ["Pryce Jones was apprenticed to a draper in Newtown at the age of twelve and opened his own shop in 1856. When the railway and the new penny post reached mid Wales, he had an idea: he sent out leaflets describing his Welsh flannel, and customers ordered by letter and received their goods by post and rail.",
    "It was the first mail-order business in the world. By the 1880s he had a hundred thousand customers, among them Queen Victoria and Florence Nightingale, and the Royal Welsh Warehouse still stands beside Newtown station. He also invented the Euklisia rug, an early sleeping bag, and sold sixty thousand of them to the Russian army."],
   ["Prentisiwyd Pryce Jones i ddilledydd yn y Drenewydd yn ddeuddeg oed ac agorodd ei siop ei hun yn 1856. Pan gyrhaeddodd y rheilffordd a’r post ceiniog newydd y canolbarth, cafodd syniad: anfonodd daflenni yn disgrifio’i wlanen Gymreig, ac archebai cwsmeriaid drwy lythyr a derbyn eu nwyddau drwy’r post a’r rheilffordd.",
    "Dyna’r busnes archebu drwy’r post cyntaf yn y byd. Erbyn y 1880au roedd ganddo gan mil o gwsmeriaid, yn eu plith y Frenhines Fictoria a Florence Nightingale, ac mae’r Royal Welsh Warehouse yn sefyll wrth orsaf y Drenewydd o hyd. Dyfeisiodd hefyd ryg Euklisia, sach gysgu gynnar, a gwerthu trigain mil ohonynt i fyddin Rwsia."],
   first=("world", "The world’s first mail-order business, Newtown 1861", "Busnes archebu drwy’r post cyntaf y byd, y Drenewydd 1861", 1861)),
 P("william-preece", "industrial", "1834–1913", "Sir William Preece", "Syr William Preece", "Champion of wireless", "Hyrwyddwr y diwifr", "William_Preece", "science",
   "Engineer from Caernarfon who brought the telephone to Britain and backed Marconi’s first wireless message across the sea, from Wales in 1897.",
   "Peiriannydd o Gaernarfon a ddaeth â’r ffôn i Brydain ac a gefnogodd neges ddiwifr gyntaf Marconi dros y môr, o Gymru yn 1897.",
   ["William Henry Preece was born in Caernarfon and rose to be engineer-in-chief of the Post Office, in charge of the telegraphs of Britain. In 1877 he brought the first pair of Bell telephones to Britain and demonstrated them to the country.",
    "When the young Guglielmo Marconi arrived in London in 1896, Preece gave him the backing of the Post Office. On 13 May 1897, at Lavernock Point near Penarth, Marconi and Preece’s engineers sent the first wireless message ever to cross open sea, to Flat Holm island: ‘Are you ready?’ Preece also pioneered wireless signalling to ships and islands from the coast of Wales."],
   ["Ganed William Henry Preece yng Nghaernarfon a chododd i fod yn brif beiriannydd Swyddfa’r Post, yng ngofal telegraffau Prydain. Yn 1877 daeth â’r pâr cyntaf o ffonau Bell i Brydain a’u harddangos i’r wlad.",
    "Pan gyrhaeddodd Guglielmo Marconi ifanc Lundain yn 1896, rhoddodd Preece gefnogaeth Swyddfa’r Post iddo. Ar 13 Mai 1897, ym Mhwynt Larnog ger Penarth, anfonodd Marconi a pheirianwyr Preece y neges ddiwifr gyntaf erioed i groesi’r môr agored, i ynys Echni: ‘Are you ready?’ Arloesodd Preece hefyd signalau diwifr i longau ac ynysoedd o arfordir Cymru."],
   first=("world", "The first wireless message across open sea, Lavernock to Flat Holm, 1897", "Y neges ddiwifr gyntaf dros y môr agored, Larnog i Ynys Echni, 1897", 1897)),
 P("daniel-owen", "industrial", "1836–1895", "Daniel Owen", "Daniel Owen", "The great Welsh novelist", "Nofelydd mawr y Gymraeg", "Daniel_Owen", "words",
   "Tailor of Mold whose novels Rhys Lewis and Enoc Huws made him the greatest Welsh novelist of the nineteenth century.",
   "Teiliwr o’r Wyddgrug y gwnaeth ei nofelau Rhys Lewis ac Enoc Huws ef yn nofelydd Cymraeg mwyaf y bedwaredd ganrif ar bymtheg.",
   ["Daniel Owen was born in Mold in 1836. His father and two brothers were drowned in a pit flood when he was a baby, and he went to work as a tailor’s apprentice at twelve. He taught himself in the tailor’s shop, where the men argued about books and religion as they sewed.",
    "His novels, Rhys Lewis, Enoc Huws, Gwen Tomos, are full of humour and life, and characters such as Wil Bryan became household names in Wales. His motto was ‘Nid i’r doeth a’r deallus yr ysgrifennais, ond i’r cyffredin’: not for the wise and learned did I write, but for ordinary people. His statue stands in the centre of Mold."],
   ["Ganed Daniel Owen yn yr Wyddgrug yn 1836. Boddwyd ei dad a dau frawd mewn llifogydd mewn pwll glo pan oedd yn faban, ac aeth i weithio’n brentis teiliwr yn ddeuddeg oed. Dysgodd ei hun yn siop y teiliwr, lle dadleuai’r dynion am lyfrau a chrefydd wrth wnïo.",
    "Mae ei nofelau, Rhys Lewis, Enoc Huws, Gwen Tomos, yn llawn hiwmor a bywyd, a daeth cymeriadau fel Wil Bryan yn enwau cyfarwydd ar aelwydydd Cymru. Ei arwyddair oedd ‘Nid i’r doeth a’r deallus yr ysgrifennais, ond i’r cyffredin’. Saif ei gerflun yng nghanol yr Wyddgrug."]),
 P("lewis-jones-patagonia", "industrial", "1836–1904", "Lewis Jones", "Lewis Jones", "Founder of Trelew", "Sylfaenydd Trelew", "Lewis_Jones_(Patagonia)", "explore",
   "Printer from Caernarfon who helped found the Welsh colony in Patagonia, built its railway and gave his name to the town of Trelew.",
   "Argraffydd o Gaernarfon a helpodd sefydlu’r Wladfa ym Mhatagonia, adeiladu ei rheilffordd a rhoi ei enw i dref Trelew.",
   ["Lewis Jones was a printer from Caernarfon and one of the leaders of the movement to found a Welsh-speaking colony overseas. In 1862 he travelled to Patagonia with Love Jones-Parry to see the land, and his good report helped persuade the settlers of the Mimosa to sail in 1865.",
    "He served as a leader of Y Wladfa, edited its Welsh newspaper Y Drafod, and in the 1880s pushed through the railway from the port of Puerto Madryn to the Chubut valley. The town that grew at its terminus was named Trelew, Lewis’s town, after him. His daughter Eluned Morgan became one of the finest writers of the colony."],
   ["Argraffydd o Gaernarfon oedd Lewis Jones ac un o arweinwyr y mudiad i sefydlu gwladfa Gymraeg dros y môr. Yn 1862 teithiodd i Batagonia gyda Love Jones-Parry i weld y tir, a helpodd ei adroddiad da berswadio ymfudwyr y Mimosa i hwylio yn 1865.",
    "Bu’n un o arweinwyr y Wladfa, golygodd ei phapur Cymraeg Y Drafod, ac yn y 1880au gyrrodd y rheilffordd o borthladd Porth Madryn i ddyffryn Camwy yn ei blaen. Enwyd y dref a dyfodd ar ben y lein yn Drelew, tref Lewis, ar ei ôl. Daeth ei ferch Eluned Morgan yn un o awduron gorau’r Wladfa."]),
 P("henry-morton-stanley", "industrial", "1841–1904", "Sir Henry Morton Stanley", "Syr Henry Morton Stanley", "Explorer of Africa", "Fforiwr Affrica", "Henry_Morton_Stanley", "explore",
   "Born John Rowlands in Denbigh, raised in St Asaph workhouse, he found Livingstone and was the first to follow the Congo river to the sea.",
   "Ganed yn John Rowlands yn Ninbych, a’i fagu yn wyrcws Llanelwy; daeth o hyd i Livingstone ac ef oedd y cyntaf i ddilyn afon Congo i’r môr.",
   ["John Rowlands was born in Denbigh in 1841 and spent his childhood in the workhouse at St Asaph. At seventeen he worked his passage to New Orleans, took the name of a merchant who befriended him, and became a newspaper reporter.",
    "In 1871 the New York Herald sent him to find the missionary David Livingstone, lost in central Africa, and at Ujiji on Lake Tanganyika he greeted him with the most famous words of the age: ‘Dr Livingstone, I presume?’ From 1874 to 1877 he crossed Africa from east to west and followed the Congo for its whole course to the Atlantic, the first to do so. A statue of him was raised in Denbigh in 2011."],
   ["Ganed John Rowlands yn Ninbych yn 1841 a threuliodd ei blentyndod yn wyrcws Llanelwy. Yn ddwy ar bymtheg gweithiodd ei fordaith i New Orleans, cymerodd enw masnachwr a fu’n gyfaill iddo, a daeth yn ohebydd papur newydd.",
    "Yn 1871 anfonodd y New York Herald ef i chwilio am y cenhadwr David Livingstone, a gollwyd yng nghanol Affrica, ac yn Ujiji ar Lyn Tanganyika cyfarchodd ef â geiriau enwocaf yr oes: ‘Dr Livingstone, I presume?’ Rhwng 1874 a 1877 croesodd Affrica o’r dwyrain i’r gorllewin a dilyn afon Congo ar ei hyd i Fôr Iwerydd, y cyntaf i wneud hynny. Codwyd cerflun iddo yn Ninbych yn 2011."],
   first=("world", "The first to follow the Congo river along its whole course to the sea, 1877", "Y cyntaf i ddilyn afon Congo ar ei hyd i’r môr, 1877", 1877)),
 P("frances-hoggan", "industrial", "1843–1927", "Frances Hoggan", "Frances Hoggan", "Pioneering doctor", "Meddyg arloesol", "Frances_Hoggan", "science",
   "Born in Brecon, the first British woman to gain a doctorate in medicine at a European university, in Zurich in 1870.",
   "Ganed yn Aberhonddu; y fenyw gyntaf o Brydain i ennill doethuriaeth mewn meddygaeth mewn prifysgol yn Ewrop, yn Zurich yn 1870.",
   ["Frances Morgan was born in Brecon, the daughter of a curate. British universities would not let women qualify as doctors, so she went to Zurich, and in 1870 she gained her doctorate in medicine in under three years, the first British woman to do so at a university in Europe.",
    "With her husband George Hoggan she set up the first husband-and-wife medical practice in Britain. She campaigned for girls’ secondary schools in Wales, for women doctors in India and for the rights of Black Americans, whom she visited and championed."],
   ["Ganed Frances Morgan yn Aberhonddu, yn ferch i gurad. Ni chaniatâi prifysgolion Prydain i fenywod gymhwyso’n feddygon, felly aeth i Zurich, ac yn 1870 enillodd ei doethuriaeth mewn meddygaeth mewn llai na thair blynedd, y fenyw gyntaf o Brydain i wneud hynny mewn prifysgol yn Ewrop.",
    "Gyda’i gŵr George Hoggan sefydlodd y practis meddygol gŵr a gwraig cyntaf ym Mhrydain. Ymgyrchodd dros ysgolion uwchradd i ferched yng Nghymru, dros feddygon benywaidd yn India a thros hawliau Americanwyr Du, a fu’n eu cefnogi."],
   first=("wales", "The first British woman to earn a doctorate in medicine at a European university, 1870", "Y fenyw gyntaf o Brydain i ennill doethuriaeth mewn meddygaeth mewn prifysgol yn Ewrop, 1870", 1870)),
 P("sir-john-williams", "industrial", "1840–1926", "Sir John Williams", "Syr John Williams", "Founder of the National Library", "Sylfaenydd y Llyfrgell Genedlaethol", "Sir_John_Williams,_1st_Baronet,_of_the_City_of_London", "learning",
   "Physician to Queen Victoria from Gwynfe in Carmarthenshire, whose great collection of manuscripts founded the National Library of Wales.",
   "Meddyg y Frenhines Fictoria o Wynfe yn Sir Gaerfyrddin, y sefydlodd ei gasgliad mawr o lawysgrifau Lyfrgell Genedlaethol Cymru.",
   ["John Williams was born at Gwynfe, the son of a minister, and became one of the leading doctors of London and physician to Queen Victoria and her family.",
    "All his life he collected the books and manuscripts of Wales, among them the Black Book of Carmarthen, the oldest manuscript entirely in Welsh, and the Hengwrt manuscripts. When the National Library of Wales was founded in 1907 he gave them all, and helped pay for its building on the hill above Aberystwyth. He was its first president."],
   ["Ganed John Williams yng Ngwynfe, yn fab i weinidog, a daeth yn un o feddygon blaenaf Llundain ac yn feddyg i’r Frenhines Fictoria a’i theulu.",
    "Ar hyd ei oes casglodd lyfrau a llawysgrifau Cymru, yn eu plith Llyfr Du Caerfyrddin, y llawysgrif hynaf sydd yn gyfan gwbl yn Gymraeg, a llawysgrifau Hengwrt. Pan sefydlwyd Llyfrgell Genedlaethol Cymru yn 1907 rhoddodd y cyfan, a helpodd dalu am ei hadeilad ar y bryn uwchben Aberystwyth. Ef oedd ei llywydd cyntaf."]),
 P("robert-jones-surgeon", "industrial", "1857–1933", "Sir Robert Jones", "Syr Robert Jones", "Surgeon of the wounded", "Llawfeddyg y clwyfedigion", "Robert_Jones_(surgeon)", "science",
   "Surgeon from Rhyl, one of the first in the world to use an X-ray to treat a patient, who saved thousands of soldiers in the First World War.",
   "Llawfeddyg o’r Rhyl, un o’r cyntaf yn y byd i ddefnyddio pelydr-X i drin claf, a achubodd filoedd o filwyr yn y Rhyfel Byd Cyntaf.",
   ["Robert Jones was born in Rhyl and trained under his uncle Hugh Owen Thomas in Liverpool. In 1896, only weeks after Röntgen announced the discovery of X-rays, he used one to find a bullet in a boy’s wrist, one of the first uses of an X-ray to treat a patient anywhere.",
    "As surgeon to the building of the Manchester Ship Canal he set up the first organised accident service in the world for its 20,000 workers. In the First World War he was put in charge of military orthopaedics and brought in the Thomas splint, saving thousands of lives, and afterwards he devoted himself to children crippled by disease."],
   ["Ganed Robert Jones yn y Rhyl a hyfforddodd dan ei ewythr Hugh Owen Thomas yn Lerpwl. Yn 1896, wythnosau’n unig wedi i Röntgen gyhoeddi darganfod pelydrau-X, defnyddiodd un i ddod o hyd i fwled yn arddwrn bachgen, un o’r defnyddiau cyntaf yn unman o belydr-X i drin claf.",
    "Fel llawfeddyg adeiladu Camlas Longau Manceinion sefydlodd wasanaeth damweiniau trefnus cyntaf y byd i’w 20,000 o weithwyr. Yn y Rhyfel Byd Cyntaf fe’i rhoddwyd yng ngofal orthopedeg y fyddin a daeth â sblint Thomas i ddefnydd, gan achub miloedd o fywydau, ac wedi hynny rhoddodd ei hun i blant a anafwyd gan afiechyd."],
   first=("world", "Among the first in the world to use an X-ray to treat a patient, 1896", "Ymhlith y cyntaf yn y byd i ddefnyddio pelydr-X i drin claf, 1896", 1896)),
 P("om-edwards", "industrial", "1858–1920", "Sir O. M. Edwards", "Syr O. M. Edwards", "Who gave Wales back its history", "Y gŵr a roddodd ei hanes yn ôl i Gymru", "Owen_Morgan_Edwards", "learning",
   "Historian from Llanuwchllyn who wrote for the ordinary people of Wales, founded Cymru’r Plant and put Welsh back into the schools.",
   "Hanesydd o Lanuwchllyn a ysgrifennodd i bobl gyffredin Cymru, sefydlodd Cymru’r Plant a rhoi’r Gymraeg yn ôl yn yr ysgolion.",
   ["Owen Morgan Edwards was born at Coed-y-pry, Llanuwchllyn, and as a schoolboy had the Welsh Not hung round his neck. He became a fellow of Lincoln College, Oxford, and the most loved writer of his generation.",
    "He wrote the history of Wales for its own people in their own language, and founded magazines for them, among them Cymru and Cymru’r Plant, the children’s magazine. As the first Chief Inspector of Schools for Wales from 1907 he made sure Welsh was taught, and his son Ifan ab Owen Edwards founded the Urdd."],
   ["Ganed Owen Morgan Edwards yng Nghoed-y-pry, Llanuwchllyn, ac fel plentyn ysgol cafodd y Welsh Not am ei wddf. Daeth yn gymrawd Coleg Lincoln, Rhydychen, ac yn llenor mwyaf annwyl ei genhedlaeth.",
    "Ysgrifennodd hanes Cymru i’w phobl ei hun yn eu hiaith eu hunain, a sefydlodd gylchgronau iddynt, yn eu plith Cymru a Chymru’r Plant. Fel Prif Arolygydd Ysgolion cyntaf Cymru o 1907 sicrhaodd fod y Gymraeg yn cael ei dysgu, a’i fab Ifan ab Owen Edwards a sefydlodd yr Urdd."]),
 P("billy-meredith", "industrial", "1874–1958", "Billy Meredith", "Billy Meredith", "The Welsh Wizard", "Y Dewin Cymreig", "Billy_Meredith", "sport",
   "Footballer from Chirk who played for Wales for 25 years, helped found the players’ union and played in an FA Cup semi-final at the age of 49.",
   "Pêl-droediwr o’r Waun a chwaraeodd dros Gymru am 25 mlynedd, helpodd sefydlu undeb y chwaraewyr a chwarae mewn rownd gynderfynol Cwpan FA yn 49 oed.",
   ["Billy Meredith went down the pit at Chirk at twelve and played football in his spare time. He became the first great star of the game, a winger who played with a toothpick in his mouth, for Manchester City and then Manchester United, and won the league and the FA Cup.",
    "He played for Wales from 1895 to 1920, winning 48 caps when Wales played only three games a year, and led them to their first Home Championship in 1907. He helped found the players’ union in 1907 to fight for fair pay. In 1924, at the age of 49, he played for Manchester City in an FA Cup semi-final."],
   ["Aeth Billy Meredith i lawr y pwll yn y Waun yn ddeuddeg oed a chwarae pêl-droed yn ei amser hamdden. Daeth yn seren fawr gyntaf y gêm, asgellwr a chwaraeai â phigyn dannedd yn ei geg, i Manchester City ac yna Manchester United, ac enillodd y gynghrair a Chwpan yr FA.",
    "Chwaraeodd dros Gymru o 1895 i 1920, gan ennill 48 o gapiau pan chwaraeai Cymru dair gêm y flwyddyn yn unig, a’u harwain at eu Pencampwriaeth Gartref gyntaf yn 1907. Helpodd sefydlu undeb y chwaraewyr yn 1907 i ymladd am dâl teg. Yn 1924, yn 49 oed, chwaraeodd i Manchester City mewn rownd gynderfynol Cwpan yr FA."]),
 P("stepney-davies", "industrial", "fl. 1904", "Thomas and Walter Davies", "Thomas a Walter Davies", "Inventors of the spare wheel", "Dyfeiswyr yr olwyn sbâr", "Stepney_Spare_Wheel", "enterprise",
   "Ironmonger brothers of Stepney Street, Llanelli, who invented the spare wheel in 1904. In India a spare wheel is still called a ‘stepney’.",
   "Brodyr o haearnwerthwyr Stryd Stepney, Llanelli, a ddyfeisiodd yr olwyn sbâr yn 1904. Yn India gelwir olwyn sbâr yn ‘stepney’ o hyd.",
   ["In the early days of motoring a puncture meant a long wait at the roadside, because tyres were fixed to the wheel. Thomas Morris Davies and his brother Walter, ironmongers in Stepney Street, Llanelli, came up with the answer in 1904: a spare wheel rim with a tyre already fitted, which could be clamped on in minutes.",
    "The Stepney Spare Wheel was a great success. Their factory supplied taxis in London and motorists across the Empire, and the name stuck: across India, Pakistan and Bangladesh a spare wheel is still called a stepney, after a street in Llanelli."],
   ["Yn nyddiau cynnar moduro golygai twll mewn teiar aros hir ar ochr y ffordd, am fod teiars wedi’u gosod yn sownd ar yr olwyn. Daeth Thomas Morris Davies a’i frawd Walter, haearnwerthwyr yn Stryd Stepney, Llanelli, o hyd i’r ateb yn 1904: ymyl olwyn sbâr gyda theiar arni’n barod, y gellid ei chlampio yn ei lle mewn munudau.",
    "Bu Olwyn Sbâr Stepney yn llwyddiant mawr. Cyflenwai eu ffatri dacsis yn Llundain a modurwyr ar draws yr Ymerodraeth, a glynodd yr enw: ar draws India, Pacistan a Bangladesh gelwir olwyn sbâr yn stepney o hyd, ar ôl stryd yn Llanelli."],
   first=("world", "The spare wheel, Llanelli 1904", "Yr olwyn sbâr, Llanelli 1904", 1904)),
 P("edgar-evans", "industrial", "1876–1912", "Edgar Evans", "Edgar Evans", "To the South Pole", "I Begwn y De", "Edgar_Evans_(sailor)", "explore",
   "Petty officer from Rhossili, one of the five men of Scott’s party who reached the South Pole on 17 January 1912.",
   "Is-swyddog o Rosili, un o bump o griw Scott a gyrhaeddodd Begwn y De ar 17 Ionawr 1912.",
   ["Edgar Evans was born at Middleton, Rhossili, on Gower and joined the Royal Navy at fifteen. A giant of a man, strong, cheerful and clever with his hands, he sailed with Captain Scott to Antarctica on the Discovery and again on the Terra Nova.",
    "Scott chose him for the final party of five, and on 17 January 1912 they stood at the South Pole, among the first people ever to reach it. He died on the return journey across the Beardmore Glacier. A memorial tablet to him stands in St Mary’s Church in Rhossili."],
   ["Ganed Edgar Evans yn Middleton, Rhosili, ar Benrhyn Gŵyr ac ymunodd â’r Llynges yn bymtheg oed. Cawr o ddyn, cryf, siriol a medrus â’i ddwylo, hwyliodd gyda’r Capten Scott i Antarctica ar y Discovery ac eto ar y Terra Nova.",
    "Dewisodd Scott ef ar gyfer y criw olaf o bump, ac ar 17 Ionawr 1912 safasant ar Begwn y De, ymhlith y bobl gyntaf erioed i’w gyrraedd. Bu farw ar y daith yn ôl ar draws Rhewlif Beardmore. Saif llechen goffa iddo yn Eglwys y Santes Fair yn Rhosili."],
   first=("wales", "The first Welshman to reach the South Pole, 1912", "Y Cymro cyntaf i gyrraedd Pegwn y De, 1912", 1912)),
]
